{
  "vulnerable_symbols": [
    "ThreadContext.put",
    "MDC.put",
    "Logger.info"
  ],
  "trigger": "攻击者可控字符串被写入 Log4j ThreadContext，并在含 ctx lookup 的日志 Pattern 下被记录解释时，触发无限递归 DoS。",
  "preconditions": [
    "使用受影响版本 log4j-core 2.0-alpha1 至 2.16.0（除 2.12.3）",
    "日志 Pattern 配置了 Context Lookup（如 ${ctx:...}）"
  ],
  "exploit_evidence": [
    {
      "src": 2,
      "kind": "in_the_wild",
      "quote": "VulnCheck reports CVE-2021-45105 use in known ransomware campaigns."
    },
    {
      "src": 0,
      "kind": "poc",
      "quote": "Python script that generates a self-referential Log4j2 lookup payload and sends it via HTTP GET/POST requests to trigger CVE-2021-45105 uncontrolled recursion, causing denial of service."
    },
    {
      "src": 1,
      "kind": "poc",
      "quote": "The README provides curl commands to trigger the vulnerability via HTTP headers or JSON body, and the controller code places user-controlled input into the ThreadContext, which is then logged, causing an infinite loop error."
    }
  ],
  "fixed_version": "2.17.0",
  "summary_zh": "Log4j2 在日志 Pattern 含 ctx lookup 时，攻击者可控 ThreadContext 字符串可触发无限递归，导致拒绝服务，请升级 2.17.0。"
}
